    // revision 11: what an area's own steps could not place is made up from the rest of what belongs there, each kind
    // tried once in a shuffled order: at the fence or a wall, else (a thing that may stand alone) in the open
    int PoolLen(string[] pool) { return pool.Length; }

    // FillFromPool one piece a step (planIter: which of the pool; Cor, build freezes). False when it stops.
    bool PoolStep(int k0, string[] pool)
    {
        int room = pRoom;
        if (planIter == 0) { planR = SR(k0); planB = RngRange(planR, pool.Length); }
        if (!Fit(1)) return false;
        int def = Dn(pool[(planB + planIter) % pool.Length]);
        if (CountInRoom(def, room) >= ScaledCap(defRoomCap[def], room)) return true;
        int first = nEmit;
        if (WallPlace(def, WM_ANY, 0, 0, WIN_ANY, 0, planR) >= 0 && Keep(first, false)) return true;
        if (Has(def, GenData.FL_LOOSE)) return true;
        int cell = OpenSpot(2, WM_ANY, 0, 0, 0, planR);
        first = nEmit;
        if (cell >= 0 && FreePlace(def, cell, RngRange(planR, 4) * 90, 1, 0, H_FREE) >= 0) Keep(first, false);
        return true;
    }

    void FillFromPool(int k0, string[] pool)
    {
        int room = pRoom;
        uint[] r = SR(k0);
        int p0 = RngRange(r, pool.Length);
        for (int k = 0; k < pool.Length && Fit(1); k++)
        {
            int def = Dn(pool[(p0 + k) % pool.Length]);
            if (CountInRoom(def, room) >= ScaledCap(defRoomCap[def], room)) continue;
            int first = nEmit;
            if (WallPlace(def, WM_ANY, 0, 0, WIN_ANY, 0, r) >= 0 && Keep(first, false)) continue;
            if (Has(def, GenData.FL_LOOSE)) continue;
            int cell = OpenSpot(2, WM_ANY, 0, 0, 0, r);
            first = nEmit;
            if (cell >= 0 && FreePlace(def, cell, RngRange(r, 4) * 90, 1, 0, H_FREE) >= 0) Keep(first, false);
        }
    }

